uint16_t xzd_font_cjk_count(void)
{
    return 7296;
}

uint16_t xzd_font_cjk_cp_at(uint16_t idx)
{
    return (idx < 7296) ? sg_cjk_cp[idx] : 0;
}

bool xzd_font_get_cjk(uint16_t cp, XZD_GLYPH_T *out)
{
    uint16_t lo = 0;
    uint16_t hi = 7296;

    if (NULL == out) {
        return false;
    }
    while (lo < hi) {
        uint16_t mid = (uint16_t)((lo + hi) / 2);
        uint16_t v  = sg_cjk_cp[mid];

        if (v == cp) {
            out->w = XZD_FONT_CJK_W;
            out->h = XZD_FONT_CJK_H;
            out->bits = &sg_cjk_bits[sg_cjk_off[mid]];
            return true;
        }
        if (v < cp) {
            lo = (uint16_t)(mid + 1);
        } else {
            hi = mid;
        }
    }
    return false;
}

bool xzd_font_get_ascii(char c, XZD_GLYPH_T *out)
{
    uint8_t idx;

    if (NULL == out) {
        return false;
    }
    if (c < 0x20 || c > 0x7E) {
        return false;
    }
    idx = (uint8_t)(c - 0x20);
    out->w = sg_ascii_w[idx];
    out->h = XZD_FONT_ASCII_H;
    out->bits = sg_ascii_bits[idx];
    return true;
}

bool xzd_font_get_big_digit(char c, XZD_GLYPH_T *out)
{
    uint8_t d;

    if (NULL == out) {
        return false;
    }
    if (c < '0' || c > '9') {
        return false;
    }
    d = (uint8_t)(c - '0');
    out->w = sg_big_dig[d].w;
    out->h = sg_big_dig[d].h;
    out->bits = &sg_big_bits[sg_big_dig[d].off];
    return true;
}
